<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { Download, RefreshCw, Sparkles } from '@lucide/vue'
import { can } from '../../permissions.js'
import { notifyError } from '../../api.js'
import { UiMessage } from '../../ui/feedback.js'
import { createClientId } from '../../clientId.js'
import { publishRuleLab, ruleLabAIRead, ruleLabAIWrite, ruleLabAll, ruleLabRead, ruleLabReport, ruleLabWrite } from '../../rulelab/api.js'
import { branchLabels, categoryLabels, clockPolicies, countLabel, differenceLabels, findingKinds, labelConclusions, labelRatio, metricLabels, publicationPayload, qualityLabels, reasonText, reviewStates, ruleLabTime, runIsActive, semantics, stateLabel, stateTone, unwrapOutputs } from '../../rulelab/helpers.js'
const props=defineProps({run:Object,experiment:Object,dataset:Object,devices:{type:Array,default:()=>[]},revisions:{type:Array,default:()=>[]}})
const emit=defineEmits(['navigate','refresh','open-experiment','open-input'])
const root=ref(null),loading=ref(false),error=ref(''),snapshot=ref(null),metrics=ref([]),outcomes=ref([]),diffs=ref([]),findings=ref([]),evidence=ref([]),reviews=ref([]),downloading=ref(false)
const deviceFilter=ref(''),branchFilter=ref(''),categoryFilter=ref(''),diffFilter=ref(''),reviewFilter=ref(''),eventPage=ref(1),diffPage=ref(1),findingPage=ref(1)
const dialog=ref(false),detail=ref(null),detailType=ref(''),history=ref([]),detailError=ref(''),reviewSaving=ref(false),review=reactive({result:'',explanation:'',correctsId:'',idempotencyKey:''})
const aiJobs=ref([]),aiId=ref(''),aiError=ref(''),aiBusy=ref(false),useKnowledge=ref(false)
const publishDialog=ref(false),publishBusy=ref(false),publishError=ref(''),publishReason=ref(''),publishConflicts=ref([]),conflictsConfirmed=ref(false),published=ref(null)
let generation=0,detailGeneration=0,aiTimer=0,disposed=false
const deviceName=id=>props.devices.find(row=>row.id===id)?.name||id||'跨设备固定汇总'
const ruleName=id=>props.revisions.find(row=>row.ruleId===id)?.rule?.name||id||'设备来源'
const statistics=computed(()=>snapshot.value?.statistics||{})
const baseline=computed(()=>props.revisions.find(row=>props.experiment?.body?.baselineRevisionIds.includes(row.id)&&row.ruleId===props.experiment.body.candidateRuleId))
const activeAI=computed(()=>aiJobs.value.find(row=>row.id===aiId.value)||aiJobs.value[0]),interpretation=computed(()=>activeAI.value?.interpretation||{})
const aiSections=[['behaviorDifferences','行为差异解读'],['verificationSuggestions','建议核查'],['limitations','解读限制']]
const latestReview=id=>reviews.value.filter(row=>row.resourceId===id).sort((a,b)=>b.reviewedAt-a.reviewedAt||String(b.id).localeCompare(String(a.id)))[0]
const selectedEvidence=computed(()=>detailType.value==='evidence'?[detail.value]:evidence.value.filter(row=>detail.value?.evidenceIds?.includes(row.id)))
const visibleOutcomes=computed(()=>outcomes.value.filter(row=>(!deviceFilter.value||row.deviceId===deviceFilter.value)&&(!branchFilter.value||row.branch===branchFilter.value)&&(!categoryFilter.value||row.category===categoryFilter.value)))
const visibleDiffs=computed(()=>diffs.value.filter(row=>(!diffFilter.value||row.kind===diffFilter.value)&&(!deviceFilter.value||[row.baselineId,row.candidateId].some(id=>outcomes.value.find(o=>o.id===id)?.deviceId===deviceFilter.value))))
const visibleFindings=computed(()=>findings.value.filter(row=>(!deviceFilter.value||!row.deviceId||row.deviceId===deviceFilter.value)&&(!reviewFilter.value||(latestReview(row.id)?.result||'UNREVIEWED')===reviewFilter.value)))
const eventSlice=computed(()=>visibleOutcomes.value.slice((eventPage.value-1)*20,eventPage.value*20)),diffSlice=computed(()=>visibleDiffs.value.slice((diffPage.value-1)*20,diffPage.value*20)),findingSlice=computed(()=>visibleFindings.value.slice((findingPage.value-1)*20,findingPage.value*20))
const outcome=id=>outcomes.value.find(row=>row.id===id)
const title=computed(()=>detailType.value==='finding'?(findingKinds[detail.value?.kind]||'固定发现'):detailType.value==='outcome'?'固定告警周期':'固定输入证据')
function stopAI(){clearTimeout(aiTimer);aiTimer=0}
async function loadAI(){const id=props.experiment?.id,runId=props.run?.id,token=generation;if(!id||!props.run?.snapshotId)return;try{const value=await ruleLabAIRead(id,runId);if(token!==generation||disposed)return;aiJobs.value=(value.items||[]).sort((a,b)=>b.createdAt-a.createdAt||String(b.id).localeCompare(String(a.id)));if(!aiJobs.value.some(row=>row.id===aiId.value))aiId.value=aiJobs.value[0]?.id||'';stopAI();if(aiJobs.value.some(row=>['QUEUED','RUNNING'].includes(row.status)))aiTimer=setTimeout(loadAI,2200)}catch(cause){if(token===generation&&!disposed){aiError.value=cause.message;stopAI()}}}
async function runAI(){if(aiBusy.value)return;const token=generation;aiBusy.value=true;aiError.value='';try{const current=await ruleLabRead('runs',props.run.id);if(token!==generation||disposed)return;const row=await ruleLabAIWrite(props.experiment.id,props.run.id,{expectedVersion:current.version,idempotencyKey:createClientId(),useKnowledge:useKnowledge.value,reinterpret:!!activeAI.value});if(token!==generation||disposed)return;aiId.value=row.id;await loadAI()}catch(cause){if(token===generation&&!disposed)aiError.value=cause.message}finally{if(token===generation)aiBusy.value=false}}
async function stopAIJob(){if(aiBusy.value||!activeAI.value)return;const token=generation;aiBusy.value=true;try{await ruleLabWrite('experiments',props.experiment.id,`ai-jobs/${encodeURIComponent(activeAI.value.id)}/stop`,{expectedVersion:activeAI.value.version});if(token===generation&&!disposed)await loadAI()}catch(cause){if(token===generation&&!disposed)aiError.value=cause.message}finally{if(token===generation)aiBusy.value=false}}
async function load(){const token=++generation;stopAI();detailGeneration++;dialog.value=false;publishDialog.value=false;loading.value=false;error.value='';snapshot.value=null;metrics.value=[];outcomes.value=[];diffs.value=[];findings.value=[];evidence.value=[];reviews.value=[];history.value=[];aiJobs.value=[];aiId.value='';aiError.value='';aiBusy.value=false;reviewSaving.value=false;publishBusy.value=false;deviceFilter.value='';branchFilter.value='';categoryFilter.value='';diffFilter.value='';reviewFilter.value='';if(!props.run?.snapshotId)return;loading.value=true;const id=props.run.id;try{const result=await Promise.all([ruleLabRead('runs',id,'snapshot'),...['metrics','outcomes','diffs','findings','evidence','reviews'].map(kind=>ruleLabAll('runs',id,kind))]);if(token!==generation||disposed)return;snapshot.value=result[0];metrics.value=unwrapOutputs(result[1].items);outcomes.value=unwrapOutputs(result[2].items);diffs.value=unwrapOutputs(result[3].items);findings.value=unwrapOutputs(result[4].items);evidence.value=result[5].items||[];reviews.value=result[6].items||[];eventPage.value=1;diffPage.value=1;findingPage.value=1;await loadAI()}catch(cause){if(token===generation&&!disposed){error.value=cause.message;if([403,404].includes(cause.status)){snapshot.value=null;metrics.value=[];outcomes.value=[];diffs.value=[];findings.value=[];evidence.value=[]}}}finally{if(token===generation)loading.value=false}}
async function openDetail(row,type='outcome'){if(!row)return;const token=++detailGeneration;detail.value=row;detailType.value=type;dialog.value=true;history.value=[];detailError.value='';reviewSaving.value=false;Object.assign(review,{result:'',explanation:'',correctsId:'',idempotencyKey:createClientId()});if(type!=='finding')return;try{const value=await ruleLabAll('findings',row.id,'reviews',{runId:props.run.id});if(token===detailGeneration&&!disposed)history.value=value.items||[]}catch(cause){if(token===detailGeneration&&!disposed)detailError.value=cause.message}}
async function saveReview(){if(reviewSaving.value||detailType.value!=='finding')return;const token=detailGeneration,runId=props.run.id,id=detail.value.id;reviewSaving.value=true;detailError.value='';try{if(!review.result||!review.explanation.trim())throw new Error('请选择核实结论并填写实际依据');const current=await ruleLabRead('runs',runId);if(token!==detailGeneration||disposed)return;const row=await ruleLabWrite('findings',id,'reviews',{runId,expectedRunVersion:current.version,...review,explanation:review.explanation.trim()});if(token!==detailGeneration||disposed)return;reviews.value=[...reviews.value.filter(v=>v.id!==row.id),row];history.value=[...history.value,row];Object.assign(review,{result:'',explanation:'',correctsId:'',idempotencyKey:createClientId()});UiMessage.success('人工核实记录已保存')}catch(cause){if(token===detailGeneration&&!disposed)detailError.value=cause.status===409?'任务或核实版本已变化，请刷新依据后重新核实。':cause.message}finally{if(token===detailGeneration)reviewSaving.value=false}}
async function exportReport(){if(downloading.value)return;downloading.value=true;try{await ruleLabReport(props.experiment.id,props.run.id)}catch(cause){notifyError(cause)}finally{downloading.value=false}}
function raw(row){if(row.rawMessageId)emit('navigate','raw',{deviceId:row.deviceId,messageId:row.rawMessageId})}
function selectFact(id){const f=findings.value.find(row=>row.id===id);if(f)return openDetail(f,'finding');const o=outcomes.value.find(row=>row.id===id);if(o)return openDetail(o);const e=evidence.value.find(row=>row.id===id);if(e)return openDetail(e,'evidence');const d=diffs.value.find(row=>row.id===id);if(d)return openDetail(outcome(d.candidateId)||outcome(d.baselineId));root.value?.querySelector('.lab-snapshot')?.scrollIntoView({block:'start'})}
function closePublish(){publishDialog.value=false;if(published.value)emit('refresh')}
function beginPublish(){publishReason.value='';publishError.value='';publishConflicts.value=[];conflictsConfirmed.value=false;published.value=null;publishDialog.value=true}
async function publish(){if(publishBusy.value)return;const token=generation;publishBusy.value=true;publishError.value='';try{if(publishConflicts.value.length&&!conflictsConfirmed.value)throw new Error('请先核实并明确确认当前冲突');const body=publicationPayload(props.experiment,props.revisions,publishReason.value);const value=await publishRuleLab(body.rule.id,body,conflictsConfirmed.value);if(token!==generation||disposed)return;published.value=value;UiMessage.success('候选已按固定版本发布，生产规则历史已更新')}catch(cause){if(token===generation&&!disposed){if(cause.status===409&&cause.details?.conflicts){publishConflicts.value=cause.details.conflicts;conflictsConfirmed.value=false;publishError.value='检测到与其他规则的实际冲突，请核实后再确认发布。'}else publishError.value=cause.status===409?'当前生产规则已发生变化，发布未执行。请读取新的规则版本并建立新实验后重试。':cause.message}}finally{if(token===generation)publishBusy.value=false}}
watch(()=>[props.run?.id,props.run?.snapshotId,props.experiment?.id],load,{immediate:true})
watch([deviceFilter,branchFilter,categoryFilter,diffFilter,reviewFilter],()=>{eventPage.value=1;diffPage.value=1;findingPage.value=1})
onBeforeUnmount(()=>{disposed=true;generation++;detailGeneration++;stopAI()})
</script>
<template><section ref="root" class="lab-stack rule-lab-results"><div class="lab-toolbar"><h3>固定分支结果</h3><div class="lab-actions"><ui-button size="small" :loading="loading" @click="load"><RefreshCw/>刷新结果</ui-button><ui-button v-if="run.snapshotId&&can('GET /api/v1/rule-lab/experiments/:id/report')" size="small" :loading="downloading" @click="exportReport"><Download/>导出实验报告</ui-button></div></div><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-skeleton v-if="loading&&!snapshot" :rows="5"/><ui-empty v-else-if="!run.snapshotId" :description="runIsActive(run)?'任务正在生成固定分支结果，请稍后查看。':'该任务没有可用比较快照，请检查执行状态。'"/>
<template v-else-if="snapshot"><div class="lab-card lab-stack lab-snapshot"><div class="lab-toolbar"><strong>固定快照版本 {{snapshot.version}} · 截至 {{ruleLabTime(snapshot.dataCutoff)}}</strong><ui-tag :type="stateTone(run.status)">{{stateLabel(run.status)}}</ui-tag></div><p class="lab-meta">固定输入 {{countLabel(statistics.sourceInputCount)}} 条 · 实际计算 {{countLabel(statistics.processedWorkItems)}} / {{countLabel(statistics.totalWorkItems)}} 个工作项<br>明细保留 {{countLabel(statistics.representedOutputCount)}} / {{countLabel(statistics.originalOutputCount)}} 项 · 代表证据 {{countLabel(statistics.evidenceCount)}} 条</p><p>{{clockPolicies[dataset?.clockPolicy] || dataset?.clockPolicy}}<br>{{semantics[dataset?.semanticsVersion] || dataset?.semanticsVersion}}</p><p class="lab-hint">初态：{{reasonText(snapshot.initialStateQuality)}} · 重现质量：{{qualityLabels[statistics.reproductionQuality] || reasonText(statistics.reproductionQuality)}} · {{experiment.body.evaluationPolicy.split==='HOLDOUT'?'留出评价':'调参比较'}}<br>基线采用 {{experiment.body.baselinePolicy==='RECORDED_ACTIVATIONS'?'真实生效历史':'选定固定版本'}}，候选在独立状态与计时中计算。</p><ui-button size="small" @click="emit('open-input')">查看本次固定输入与原值曲线</ui-button><ui-alert v-for="reason in snapshot.limitations || []" :key="reason" :title="reasonText(reason)" type="warning" :closable="false"/><p v-if="snapshot.missingSources?.length" class="lab-hint">来源缺口：{{snapshot.missingSources.map(reasonText).join('；')}}</p><p v-if="snapshot.uncomputableMetrics?.length" class="lab-hint">不可计算：{{snapshot.uncomputableMetrics.map(reasonText).join('；')}}</p><div class="lab-table-scroll"><table class="lab-native-table"><thead><tr><th>固定来源 / 版本</th><th>覆盖区间</th><th>读取时点</th><th>完整性 / 限制</th></tr></thead><tbody><tr v-for="source in snapshot.sources || []" :key="source.source+source.start"><td>{{source.source}}<p class="lab-meta">{{source.version}}</p></td><td>{{ruleLabTime(source.start)}} 至 {{ruleLabTime(source.end)}}</td><td>{{ruleLabTime(source.readAt)}}</td><td>{{source.complete?'已覆盖':'部分或未知'}} {{reasonText(source.reason)}}</td></tr></tbody></table></div><ui-collapse><ui-collapse-item title="本次固定基线与候选正文" name="configuration"><article v-for="id in experiment.body.baselineRevisionIds" :key="id"><strong>{{ruleName(revisions.find(row=>row.id===id)?.ruleId)}} · 基线版本 {{revisions.find(row=>row.id===id)?.version}}</strong><p class="lab-meta">注册 {{ruleLabTime(revisions.find(row=>row.id===id)?.registeredAt)}} · {{id}}</p><p v-if="revisions.find(row=>row.id===id)?.initialRegistration" class="lab-hint">首次登记，不推断此前生效历史</p><pre class="lab-json">{{JSON.stringify(revisions.find(row=>row.id===id)?.rule || {},null,2)}}</pre></article><p class="lab-hint">候选正文已禁用 · 本次分支 {{experiment.body.candidateEnabled?'启用':'禁用'}}</p><pre class="lab-json">{{JSON.stringify(experiment.body.candidate,null,2)}}</pre></ui-collapse-item></ui-collapse></div>
<div class="lab-card lab-stack lab-branch-metrics"><h3>两分支行为计数</h3><div class="lab-table-scroll"><table class="lab-native-table"><thead><tr><th>真实计数项</th><th v-for="branch in ['BASELINE','CANDIDATE']" :key="branch">{{branchLabels[branch]}}</th></tr></thead><tbody><tr v-for="[key,label] in Object.entries(metricLabels)" :key="key"><th>{{label}}</th><td v-for="branch in ['BASELINE','CANDIDATE']" :key="branch" :data-lab-counter="branch+':'+key">{{countLabel(metrics.find(row=>row.branch===branch)?.counters?.[key])}}</td></tr><tr><th>因缺失依据未能计算的消息</th><td v-for="branch in ['BASELINE','CANDIDATE']" :key="branch">{{countLabel(metrics.find(row=>row.branch===branch)?.counters?.uncomputedMessages)}}</td></tr></tbody></table></div><p class="lab-hint">意向动作只统计实验规则意图；实际通知送达不参与模拟。设备直接告警与部件告警周期分别保留，重复报告不会当作新的真实事件。</p></div>
<div class="lab-grid lab-evaluation"><article v-for="m in metrics" :key="m.id" class="lab-card lab-stack"><strong>{{branchLabels[m.branch]}} · {{qualityLabels[m.labelEvaluation?.status] || '评价依据未知'}}</strong><div class="lab-toolbar"><span>共同区间准确率 {{labelRatio(m.labelEvaluation,'precision')}}</span><span>共同区间检出率 {{labelRatio(m.labelEvaluation,'recall')}}</span></div><p class="lab-meta">TP {{countLabel(m.labelEvaluation?.tp)}} / 可评价告警周期 {{countLabel(m.labelEvaluation?.alarmCycles)}}<br>TP {{countLabel(m.labelEvaluation?.tp)}} / 可评价真实事件 {{countLabel(m.labelEvaluation?.realEvents)}}<br>共同区间额外提醒 {{countLabel(m.labelEvaluation?.extraCycles)}}<br>{{m.labelEvaluation?.independentValidation?'固定留出区间首次使用':'本次不属于独立留出验证'}}</p><p v-for="reason in m.labelEvaluation?.limitations || []" :key="reason" class="lab-hint">{{reasonText(reason)}}</p><ui-collapse><ui-collapse-item title="固定共同评价集合与排除标签" name="labels"><article v-for="label in m.labelEvaluation?.commonEvaluationSet || []" :key="label.id"><p>{{deviceName(label.body.deviceId)}} · {{labelConclusions[label.body.conclusion]}}<br>{{ruleLabTime(label.body.start)}} 至 {{ruleLabTime(label.body.end)}}</p><p class="lab-meta">{{label.body.basis}} · 确认 {{label.body.confirmedBy}} / {{ruleLabTime(label.body.confirmedAt)}}</p></article><p v-if="m.labelEvaluation?.excludedLabelIds?.length" class="lab-hint">测试或未知标签不作负样本：{{m.labelEvaluation.excludedLabelIds.join('、')}}</p><div class="lab-table-scroll"><table class="lab-native-table"><thead><tr><th>共同标签</th><th>匹配周期</th><th>固定差值</th></tr></thead><tbody><tr v-for="match in m.labelEvaluation?.matching || []" :key="match.id"><td>{{match.labelId}}</td><td><ui-button text size="small" @click="openDetail(outcome(match.candidateId))">周期依据</ui-button></td><td>{{match.differenceMs}} ms</td></tr></tbody></table></div></ui-collapse-item></ui-collapse></article></div>
<div class="lab-filter-row"><ui-select v-model="deviceFilter" clearable placeholder="全部获授权设备"><ui-option v-for="id in snapshot.deviceIds || run.deviceIds" :key="id" :value="id" :label="deviceName(id)"/></ui-select><ui-select v-model="branchFilter" clearable placeholder="两分支"><ui-option v-for="[value,label] in Object.entries(branchLabels)" :key="value" :value="value" :label="label"/></ui-select><ui-select v-model="categoryFilter" clearable placeholder="全部周期类别"><ui-option v-for="value in [...new Set(outcomes.map(row=>row.category))]" :key="value" :value="value" :label="categoryLabels[value] || value"/></ui-select></div>
<div class="lab-card lab-stack"><h3>周期触发与恢复</h3><div class="lab-table-scroll"><ui-table :data="eventSlice" empty-text="本次固定范围没有该类告警周期。"><ui-table-column label="设备 / 分支 / 来源" min-width="210"><template #default="{row}">{{deviceName(row.deviceId)}}<p class="lab-meta">{{branchLabels[row.branch]}} · {{categoryLabels[row.category] || row.category}}<br>{{ruleName(row.ruleId)}} · {{row.alarmType}}</p></template></ui-table-column><ui-table-column label="处理时钟触发 / 恢复" min-width="230"><template #default="{row}">{{ruleLabTime(row.triggeredAt)}}<p class="lab-meta">恢复 {{ruleLabTime(row.recoveredAt)}} · {{stateLabel(row.status)}}</p></template></ui-table-column><ui-table-column label="设备事件触发 / 恢复" min-width="230"><template #default="{row}">{{ruleLabTime(row.triggerEventAt)}}<p class="lab-meta">恢复 {{ruleLabTime(row.recoveredEventAt)}}<br>报告 {{countLabel(row.triggerCount)}} 次 · 意向动作 {{countLabel(row.intentActionCount)}}</p></template></ui-table-column><ui-table-column label="操作" width="100"><template #default="{row}"><ui-button :data-lab-outcome="row.id" text size="small" @click="openDetail(row)">周期依据</ui-button></template></ui-table-column></ui-table></div><ui-pagination :current-page="eventPage" :page-size="20" :total="visibleOutcomes.length" @current-change="eventPage=$event"/></div>
<div class="lab-card lab-stack"><div class="lab-toolbar"><h3>一对一行为差异</h3><ui-select v-model="diffFilter" clearable placeholder="全部行为差异" style="width:180px"><ui-option v-for="[value,label] in Object.entries(differenceLabels)" :key="value" :value="value" :label="label"/></ui-select></div><p class="lab-hint">策略 {{experiment.body.evaluationPolicy.version}} · 时间容差 {{experiment.body.evaluationPolicy.toleranceMs}} ms · 按{{experiment.body.evaluationPolicy.matchTimeBasis==='EVENT'?'设备事件时间':'处理时钟'}}匹配 · 每个额外周期单独计数。共同 {{countLabel(statistics.commonEvents)}} / 基线独有 {{countLabel(statistics.baselineOnly)}} / 候选独有 {{countLabel(statistics.candidateOnly)}}；差异只描述固定行为。</p><div class="lab-table-scroll"><ui-table :data="diffSlice" empty-text="该范围没有保留的行为差异明细。"><ui-table-column label="差异 / 设备" min-width="170"><template #default="{row}">{{differenceLabels[row.kind]}}<p class="lab-meta">{{deviceName(outcome(row.baselineId)?.deviceId || outcome(row.candidateId)?.deviceId)}}</p></template></ui-table-column><ui-table-column label="基线周期" min-width="210"><template #default="{row}"><ui-button v-if="row.baselineId" text size="small" @click="openDetail(outcome(row.baselineId))">{{ruleLabTime(outcome(row.baselineId)?.triggeredAt)}}</ui-button><span v-else>无共同基线周期</span></template></ui-table-column><ui-table-column label="候选周期" min-width="210"><template #default="{row}"><ui-button v-if="row.candidateId" text size="small" @click="openDetail(outcome(row.candidateId))">{{ruleLabTime(outcome(row.candidateId)?.triggeredAt)}}</ui-button><span v-else>无共同候选周期</span></template></ui-table-column><ui-table-column label="候选减基线" min-width="140"><template #default="{row}">{{row.kind==='COMMON'?row.differenceMs+' ms':'不适用'}}</template></ui-table-column></ui-table></div><ui-pagination :current-page="diffPage" :page-size="20" :total="visibleDiffs.length" @current-change="diffPage=$event"/></div>
<div class="lab-card lab-stack"><div class="lab-toolbar"><h3>固定发现与人工核实</h3><ui-select v-model="reviewFilter" clearable placeholder="全部核实状态" style="width:180px"><ui-option v-for="[value,label] in Object.entries(reviewStates)" :key="value" :value="value" :label="label"/></ui-select></div><div class="lab-table-scroll"><ui-table :data="findingSlice" empty-text="本次没有该类固定发现。"><ui-table-column label="发现" min-width="210"><template #default="{row}">{{findingKinds[row.kind] || row.kind}}<p class="lab-meta">{{deviceName(row.deviceId)}}</p></template></ui-table-column><ui-table-column label="确定性依据" min-width="300"><template #default="{row}">{{reasonText(row.explanation)}}<p class="lab-meta">{{JSON.stringify(row.values || {})}}</p></template></ui-table-column><ui-table-column label="人工状态" min-width="150"><template #default="{row}">{{reviewStates[latestReview(row.id)?.result || 'UNREVIEWED']}}</template></ui-table-column><ui-table-column label="操作" width="100"><template #default="{row}"><ui-button :data-lab-finding="row.id" text size="small" @click="openDetail(row,'finding')">依据与核实</ui-button></template></ui-table-column></ui-table></div><ui-pagination :current-page="findingPage" :page-size="20" :total="visibleFindings.length" @current-change="findingPage=$event"/></div>
<div class="lab-card lab-stack lab-ai"><div class="lab-toolbar"><h3>AI 解读版本</h3><div class="lab-actions"><ui-checkbox v-model="useKnowledge" :disabled="aiBusy">本次引用已授权知识</ui-checkbox><ui-button v-if="can('POST /api/v1/rule-lab/experiments/:id/ai-jobs')" type="primary" size="small" :loading="aiBusy" :disabled="aiJobs.some(row=>['QUEUED','RUNNING'].includes(row.status))" @click="runAI"><Sparkles/>{{activeAI?'重新解读':'开始 AI 解读'}}</ui-button><ui-button v-if="['QUEUED','RUNNING'].includes(activeAI?.status)&&can('POST /api/v1/rule-lab/experiments/:id/ai-jobs/:jobId/stop')" size="small" :loading="aiBusy" @click="stopAIJob">停止解读</ui-button></div></div><p class="lab-hint">AI 单独版本引用本次固定事实。解释或候选建议不改变标签、模拟结果与生产规则。</p><ui-alert v-if="aiError" :title="aiError" type="error" :closable="false"/><ui-empty v-if="!aiJobs.length" description="尚未显式运行 AI 解读，人工核实与报告导出可直接使用。"/><template v-else><ui-select v-model="aiId" placeholder="选择固定 AI 解读版本"><ui-option v-for="job in aiJobs" :key="job.id" :value="job.id" :label="`版本 ${job.version} · ${stateLabel(job.status)} · ${ruleLabTime(job.createdAt)}`"/></ui-select><p class="lab-meta">{{stateLabel(activeAI.status)}} · 固定事实 {{activeAI.factsHash}} · 工作流 {{activeAI.workflowId || 'rule-policy-analyst'}}</p><ui-alert v-if="activeAI.error" :title="activeAI.error" type="error" :closable="false"/><p v-if="activeAI.status==='FAILED'" class="lab-hint">AI 执行失败，固定分支事实、人工核实和实验报告仍可使用。</p><template v-if="activeAI.status==='SUCCEEDED'"><p>{{interpretation.summary}}</p><div v-for="[key,label] in aiSections" :key="key" class="lab-stack"><strong>{{label}}</strong><article v-for="(statement,i) in interpretation[key] || []" :key="i"><p>{{statement.text}}</p><div class="lab-tags"><ui-button v-for="id in statement.factIds || []" :key="id" text size="small" @click="selectFact(id)">查看引用事实</ui-button><ui-tag v-for="id in statement.deviceIds || []" :key="id" size="small">{{deviceName(id)}}</ui-tag></div></article></div><p class="lab-meta">解读覆盖 {{JSON.stringify(activeAI.coverage || interpretation.coverage || {})}}</p><ui-button v-if="interpretation.candidateRevisionId" size="small" @click="emit('open-experiment',interpretation.candidateRevisionId)">查看已验证的禁用候选新版本</ui-button><p v-if="interpretation.candidateDraft&&!interpretation.candidateRevisionId" class="lab-hint">候选未形成可用平台版本，请核实模型或平台校验结果。</p></template></template></div>
<div class="lab-card lab-stack"><div class="lab-toolbar"><h3>发布已测试候选</h3><ui-button v-if="can('POST /api/v1/rules/:id/publish')&&can('menu:rules')" type="warning" size="small" :disabled="!baseline||!['SUCCEEDED','PARTIAL'].includes(run.status)" @click="beginPublish">审阅并发布固定候选</ui-button></div><p class="lab-hint">发布目标 {{ruleName(experiment.body.candidateRuleId)}} · 基线版本 {{baseline?.version ?? '不可读取'}} · 发布后 {{experiment.body.candidateEnabled?'启用':'禁用'}}。原因与冲突需人工确认；生产版本发生变化时拒绝发布。</p><p v-if="!can('POST /api/v1/rules/:id/publish')||!can('menu:rules')" class="lab-hint">发布需要当前生产规则管理权限及完整设备管理范围。实验范围与生产发布权限分别校验。</p></div></template></section>
<ui-dialog v-model="dialog" :title="title" width="min(940px,94vw)" @close="dialog=false"><div v-if="detail" class="lab-dialog-body"><ui-alert v-if="detailError" :title="detailError" type="error" :closable="false"/><template v-if="detailType==='outcome'"><strong>{{deviceName(detail.deviceId)}} · {{branchLabels[detail.branch]}} · {{categoryLabels[detail.category] || detail.category}}</strong><p class="lab-meta">触发处理 {{ruleLabTime(detail.triggeredAt)}} · 设备事件 {{ruleLabTime(detail.triggerEventAt)}}<br>恢复处理 {{ruleLabTime(detail.recoveredAt)}} · 设备事件 {{ruleLabTime(detail.recoveredEventAt)}}<br>最新处理触发 {{ruleLabTime(detail.lastTriggeredAt)}} · 报告 {{countLabel(detail.triggerCount)}} 次</p><p class="lab-meta">周期产生版本 {{detail.createdRuleRevision || '无规则版本'}}<br>触发求值版本 {{detail.triggerRuleRevision || '无规则版本'}}<br>初态 {{reasonText(detail.initialStateQuality)}} · 意向动作 {{countLabel(detail.intentActionCount)}} / {{detail.intentActionTypes?.join('、')}}</p><p v-for="reason in detail.uncertainties || []" :key="reason" class="lab-hint">{{reasonText(reason)}}</p></template><template v-if="detailType==='finding'"><p>{{reasonText(detail.explanation)}}</p><pre class="lab-json">{{JSON.stringify(detail.values || {},null,2)}}</pre></template><article v-for="ev in selectedEvidence" :key="ev.id" class="lab-card lab-stack"><strong>固定输入 · {{deviceName(ev.deviceId)}}</strong><p class="lab-meta">{{ev.summary?.messageType}} · 事件 {{ruleLabTime(ev.summary?.eventAt || ev.occurredAt)}}<br>接收 {{ruleLabTime(ev.summary?.receivedAt)}} · 首次可查询 {{ruleLabTime(ev.summary?.availableAt)}}<br>{{ev.summary?.availableAtSource || '可查询来源未知'}} · {{reasonText(ev.originalAvailability)}}</p><p class="lab-meta">协议 {{ev.summary?.protocolVersion || '未知'}} · 配置 {{ev.summary?.configurationVersion || '未知'}} · 点表 {{ev.summary?.pointTableVersion || '未知'}}<br>固定元数据 {{ev.summary?.metadataQuality}} · 事实哈希 {{ev.summary?.frozenInputHash || ev.resourceVersion}}</p><div class="lab-table-scroll"><table class="lab-native-table"><thead><tr><th>原值属性</th><th>固定原值</th><th>历史单位</th></tr></thead><tbody><tr v-for="[key,value] in Object.entries(ev.summary?.properties || {})" :key="key"><th>{{key}}</th><td>{{typeof value==='object'?JSON.stringify(value):value}}</td><td>{{ev.summary?.units?.[key] || '未知'}}</td></tr></tbody></table></div><ui-button v-if="ev.rawMessageId&&can('menu:raw')" size="small" @click="raw(ev)">读取关联原文</ui-button><p class="lab-hint">原件当前可用性需由原文接口核实；固定输入原值保留。</p></article><p v-if="!selectedEvidence.length" class="lab-hint">此项没有保留可关联的代表输入证据。固定汇总与缺失限制保留，请检查输入覆盖及报告。</p><template v-if="detailType==='finding'"><h3>人工核实历史</h3><article v-for="row in history" :key="row.id" class="lab-card"><strong>{{reviewStates[row.result]}}</strong><p>{{row.explanation}}</p><p class="lab-meta">{{row.reviewer}} · {{ruleLabTime(row.reviewedAt)}}{{row.correctsId?' · 更正前次记录':''}}</p></article><ui-empty v-if="!history.length" description="尚未进行人工核实。"/><ui-form v-if="can('POST /api/v1/rule-lab/findings/:id/reviews')" label-position="top" :disabled="reviewSaving"><ui-form-item label="核实结论" required><ui-select v-model="review.result"><ui-option v-for="[value,label] in Object.entries(reviewStates).filter(([key])=>key!=='UNREVIEWED')" :key="value" :value="value" :label="label"/></ui-select></ui-form-item><ui-form-item label="实际核实依据" required><ui-input v-model="review.explanation" type="textarea" :rows="3" maxlength="4000"/></ui-form-item><ui-form-item v-if="history.length" label="更正原记录"><ui-select v-model="review.correctsId" clearable placeholder="追加本次核实，或明确更正的原记录"><ui-option v-for="row in history" :key="row.id" :value="row.id" :label="`${reviewStates[row.result]} · ${ruleLabTime(row.reviewedAt)}`"/></ui-select></ui-form-item></ui-form></template></div><template #footer><ui-button @click="dialog=false">关闭</ui-button><ui-button v-if="detailType==='finding'&&can('POST /api/v1/rule-lab/findings/:id/reviews')" type="primary" :loading="reviewSaving" @click="saveReview">保存核实依据</ui-button></template></ui-dialog>
<ui-dialog v-model="publishDialog" title="审阅固定候选并发布" width="min(860px,94vw)" :close-on-click-modal="false" @close="closePublish"><div class="lab-dialog-body"><ui-alert v-if="publishError" :title="publishError" type="error" :closable="false"/><ui-alert v-if="published" title="候选已发布" type="success" :closable="false">新生产版本 {{published.version}} · {{ruleLabTime(published.registeredAt)}}</ui-alert><p>目标 {{ruleName(experiment.body.candidateRuleId)}} · 预期生产基线版本 {{baseline?.version}}<br>固定实验版本 {{experiment.version}} · 发布后 {{experiment.body.candidateEnabled?'启用':'禁用'}}</p><p class="lab-hint">候选正文采用本实验固定版本，发布不临时改动阈值、持续时间或启用设置。</p><pre class="lab-json">{{JSON.stringify({...experiment.body.candidate,enabled:experiment.body.candidateEnabled},null,2)}}</pre><ui-form label-position="top" :disabled="publishBusy||!!published"><ui-form-item label="发布原因" required><ui-input v-model="publishReason" type="textarea" :rows="3" maxlength="2000"/></ui-form-item></ui-form><template v-if="publishConflicts.length"><h3>当前实际规则冲突</h3><pre class="lab-json">{{JSON.stringify(publishConflicts,null,2)}}</pre><ui-checkbox v-model="conflictsConfirmed" :disabled="publishBusy">已核实以上冲突，确认以该固定候选发布</ui-checkbox></template></div><template #footer><ui-button :disabled="publishBusy" @click="closePublish">关闭</ui-button><ui-button v-if="!published" type="warning" :loading="publishBusy" :disabled="!!publishConflicts.length&&!conflictsConfirmed" @click="publish">确认发布固定候选</ui-button></template></ui-dialog>
</template>
<style scoped>.lab-json{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;line-height:1.65;padding:10px;background:var(--surface-soft);border-radius:6px;max-height:330px;overflow:auto}.lab-evaluation{gap:14px}.rule-lab-results h3{font-size:14px;margin:0}.lab-evaluation article>strong{font-size:13px}</style>
